function groupAnagrams(strs) {
  const groups = new Map();

  for (const str of strs) {
    const key = str.split("").sort().join("");
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key).push(str);
  }

  return [...groups.values()];
}

function isPalindrome(s) {
  const isAlphanumeric = (char) => /[a-z0-9]/i.test(char);

  let left = 0;
  let right = s.length - 1;

  while (left < right) {
    while (left < right && !isAlphanumeric(s[left])) left++;
    while (left < right && !isAlphanumeric(s[right])) right--;

    if (s[left].toLowerCase() !== s[right].toLowerCase()) {
      return false;
    }

    left++;
    right--;
  }

  return true;
}

function longestPalindrome(s) {
  if (s.length < 1) return "";

  let start = 0;
  let maxLen = 1;

  const expand = (left, right) => {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      left--;
      right++;
    }
    // after the loop, (left+1, right-1) are the palindrome bounds
    const len = right - left - 1;
    if (len > maxLen) {
      maxLen = len;
      start = left + 1;
    }
  };

  for (let i = 0; i < s.length; i++) {
    expand(i, i);     // odd-length palindromes centered at i
    expand(i, i + 1); // even-length palindromes centered between i and i+1
  }

  return s.slice(start, start + maxLen);
}

function countSubstrings(s) {
  let count = 0;

  const expand = (left, right) => {
    while (left >= 0 && right < s.length && s[left] === s[right]) {
      count++;
      left--;
      right++;
    }
  };

  for (let i = 0; i < s.length; i++) {
    expand(i, i);     // odd-length palindromes centered at i
    expand(i, i + 1); // even-length palindromes centered between i and i+1
  }

  return count;
}
